'use strict';

const KEY320T2='cis320-test2-v1';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const shuffle=items=>{const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};
const shuffledOrder=items=>{const copy=shuffle(items);if(copy.length>1&&copy.every((item,index)=>item===items[index]))copy.push(copy.shift());return copy};
const paragraphs=text=>String(text||'').split(/\n+/).filter(Boolean).flatMap(paragraph=>{const sentences=paragraph.split(/(?<=[.!?])\s+(?=[A-Z0-9])/),groups=[];for(let i=0;i<sentences.length;i+=2)groups.push(sentences.slice(i,i+2).join(' '));return groups}).map(paragraph=>`<p>${esc(paragraph)}</p>`).join('');

let D,section=0,view='teach',session=null,lesson=null,subnetCase=null,subnetStep=0,storageOK=true;
let progress={cards:{},lessons:{},xp:0,days:[],completedSessions:[]};
try{const saved=JSON.parse(localStorage.getItem(KEY320T2));if(saved&&saved.cards&&typeof saved.xp==='number')progress={...progress,...saved,lessons:saved.lessons||{},completedSessions:saved.completedSessions||[]}}catch{storageOK=false}

function save(){try{localStorage.setItem(KEY320T2,JSON.stringify(progress))}catch{storageOK=false}stats()}
function stats(){if(!$('#stats'))return;$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`;if($('#storage-status'))$('#storage-status').textContent=storageOK?'Test 2 progress saves separately in this browser.':'Browser storage is unavailable. Progress will last only for this visit.'}
function record(item,correct){const old=progress.cards[item.id]||{seen:0,level:0};const level=correct?Math.min(6,old.level+1):0;progress.cards[item.id]={seen:old.seen+1,level,completed:old.completed||correct,due:Date.now()+(correct?[1,3,7,14,30,60][level-1]*86400000:60000)};progress.xp+=correct?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save()}
const completed=item=>!!progress.cards[item.id]?.completed;
const currentSection=id=>D.sections.find(item=>item.id===id);
const filtered=items=>section?items.filter(item=>item.section===section):items;
const sourceQuestion=item=>item.number?item:D.questions.find(question=>question.number===item.source);
const sectionLabel=item=>{const group=currentSection(item.section);return group?`Chapter ${group.chapter} · ${group.title}`:'CIS 320 Test 2'};

function picker(){return `<label class="tiny">Test 2 topic <select id="section"><option value="0">All Test 2 topics</option>${D.sections.map(item=>`<option value="${item.id}" ${item.id===section?'selected':''}>Ch. ${item.chapter} · ${esc(item.title)}</option>`).join('')}</select></label>`}
function heading(title,copy){return `<div class="heading"><div><div class="eyebrow">CIS 320 / TEST 2</div><h1>${esc(title)}</h1><p class="muted">${esc(copy)}</p></div>${picker()}</div>`}
const mainNav=[['teach','☀','Learn First'],['practice','◈','Practice'],['flash','▤','Flashcards'],['connections','▧','See the connections'],['subnet','#','Subnetting tutor'],['exam','✓','Practice exam']];
const focusedNav=[['exercises','◎','20 subnet exercises'],['sort','≋','Sorting & sequences'],['cloze','▱','Fill in the blanks'],['abbrev','⌁','Abbreviations']];
const referenceNav=[['terms','Aa','Terms & definitions'],['guide','☷','Full answered guide'],['sources','↗','Source coverage']];
function navButton([id,icon,label]){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${label}</button>`}
function chrome(){stats();$('#nav').innerHTML=mainNav.map(navButton).join('')+`<details ${focusedNav.some(item=>item[0]===view)?'open':''}><summary>Focused practice</summary>${focusedNav.map(navButton).join('')}</details><details ${referenceNav.some(item=>item[0]===view)?'open':''}><summary>Reference library</summary>${referenceNav.map(navButton).join('')}</details>`;$('#modebar').innerHTML=`<button data-view="teach" class="${view==='teach'?'active':''}">Learn First</button><button data-view="practice" class="${view==='practice'?'active':''}">Practice Quiz</button><span class="tiny muted">CIS 320 · Test 2 · Ch. 5–9</span>`}
function navigate(next){view=next;session=null;lesson=null;render();window.scrollTo(0,0)}
function render(){chrome();const handlers={teach:teachHome,practice:practiceHome,flash:flashHome,connections:connectionsHome,subnet:subnetHome,exam:examHome,exercises:exercisesHome,sort:sortHome,cloze:clozeHome,abbrev:abbrevHome,terms:termsHome,guide:guideHome,sources:sourcesHome};handlers[view]();const select=$('#section');if(select)select.onchange=()=>{section=+select.value;render()}}

function sourceDetails(item){const question=sourceQuestion(item);if(!question)return '';return `<details class="question-source"><summary>Where this appears in your Test 2 material</summary><p><b>Study-guide topic ${question.number}:</b> ${esc(question.q)}</p><p class="source-note">${esc(question.sourceLabel)}${question.slides?.length?` · course slide${question.slides.length===1?'':'s'} ${question.slides.join(', ')}`:''}</p></details>`}
function teachHome(){const groups=section?D.sections.filter(item=>item.id===section):D.sections;$('#app').innerHTML=heading('Understand Test 2 before you memorize it.','Each lesson defines the words first, shows the exact action taking place, and then checks the idea without requiring typed answers.')+`<div class="notice"><b>Separate from Test 1:</b> this workspace covers only the supplied Test 2 guide, Chapters 5–9 slides, subnetting exercises, and the three unique subnetting note sets. Test 1 progress remains under its original key.</div>`+groups.map(group=>{const questions=D.questions.filter(question=>question.section===group.id),done=questions.filter(question=>progress.lessons[question.id]).length;return `<section class="card" style="margin-top:22px"><span class="tag">Chapter ${group.chapter}</span><h2>${esc(group.title)}</h2><p>${esc(group.intro)}</p><div class="bar"><span style="width:${questions.length?100*done/questions.length:0}%"></span></div><p class="tiny">${done} / ${questions.length} lessons completed</p><div class="lesson-list">${questions.map(question=>`<button data-lesson="${question.number}"><span class="badge">${question.number}</span><span class="lesson-label">${esc(question.title)}<small>${esc(question.q)}</small></span><span aria-label="${progress.lessons[question.id]?'Completed':'Not completed'}">${progress.lessons[question.id]?'✓':'→'}</span></button>`).join('')}</div></section>`}).join('')}
function learningSequence(){return D.sections.filter(group=>!section||group.id===section).flatMap(group=>D.questions.filter(question=>question.section===group.id))}
function nextLesson(number){const sequence=learningSequence(),index=sequence.findIndex(question=>question.number===number);return index<0?null:sequence[index+1]}
function continueLearning(number){const question=D.questions.find(item=>item.number===number);progress.lessons[question.id]=true;save();const next=nextLesson(number);if(next){openLesson(next.number);return}const sequence=learningSequence(),unfinished=sequence.filter(item=>!progress.lessons[item.id]);lesson=null;view='teach';chrome();$('#app').innerHTML=`<section class="card study"><span class="tag">LEARNING PATH</span><h1>${unfinished.length?'You reached the last lesson':'All selected lessons complete ✓'}</h1><p>${sequence.length-unfinished.length} / ${sequence.length} lessons completed.</p><div class="bar"><span style="width:${100*(sequence.length-unfinished.length)/sequence.length}%"></span></div><p>${unfinished.length?'Return to the first unfinished lesson so the completion bar represents every lesson read.':'You can now practice the whole selection or revisit any lesson.'}</p><div class="actions">${unfinished.length?`<button class="primary" data-lesson="${unfinished[0].number}">Continue unfinished lesson</button>`:'<button class="primary" data-view="practice">Practice what you learned</button>'}<button data-view="teach">All lessons</button></div></section>`}
function openLesson(number,step=0){view='teach';session=null;lesson={number,step};chrome();const question=D.questions.find(item=>item.number===number),labels=['Start with the basics','Complete study-guide answer','See the action happen'];$('#app').innerHTML=`<div class="study"><div class="row spread"><span class="tag">${sectionLabel(question)} · Topic ${number} / ${D.questions.length}</span><button data-view="teach">All lessons</button></div><h1>${esc(question.title)}</h1><div class="bar"><span style="width:${100*(step+1)/3}%"></span></div><section class="card lesson-copy" style="margin-top:24px"><p class="lesson-step-label">STEP ${step+1} OF 3 · ${labels[step]}</p><h2>${esc(step===1?question.q:labels[step])}</h2>${paragraphs([question.teach,question.answer,question.example][step])}${step===2?`<div class="notice"><b>Memory sentence:</b> ${esc(question.correct)}</div>`:''}${sourceDetails(question)}</section><div class="actions">${step?'<button id="lesson-prev">← Back</button>':''}${step<2?'<button class="primary" id="lesson-next">Next step →</button>':`<button class="primary" id="lesson-practice">Try this topic</button><button id="continue-learning">${nextLesson(number)?`Next lesson → ${esc(nextLesson(number).title)}`:'Finish these lessons'}</button><button id="lesson-complete">${progress.lessons[question.id]?'✓ Lesson completed':'Mark lesson read'}</button>`}</div>${question.section===5?'<p><button data-view="subnet">Open the step-by-step subnetting tutor</button></p>':''}</div>`;if($('#lesson-prev'))$('#lesson-prev').onclick=()=>openLesson(number,step-1);if($('#lesson-next'))$('#lesson-next').onclick=()=>openLesson(number,step+1);if($('#lesson-complete'))$('#lesson-complete').onclick=()=>{progress.lessons[question.id]=true;save();openLesson(number,2)};if($('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(number);if($('#lesson-practice'))$('#lesson-practice').onclick=()=>{progress.lessons[question.id]=true;save();start('practice',[question,...D.checks.filter(item=>item.source===number),...D.cloze.filter(item=>item.source===number),...D.sorts.filter(item=>item.source===number).map(item=>({...item,kind:'sort'}))],number)};$('#app').focus();window.scrollTo(0,0)}

function sectionCards(){return `<div class="grid">${D.sections.map(group=>{const questions=D.questions.filter(item=>item.section===group.id),done=questions.filter(completed).length;return `<section class="card"><span class="tag">Chapter ${group.chapter}</span><h2>${esc(group.title)}</h2><p>${esc(group.scope)}</p><div class="bar"><span style="width:${100*done/questions.length}%"></span></div><p>${done} / ${questions.length} study-guide topics answered correctly${done===questions.length?' · ✓ Complete':''}</p><button class="primary" data-practice-section="${group.id}">Practice this topic</button></section>`}).join('')}</div>`}
function mixedPool(){return [...D.questions,...D.checks,...D.vocab,...D.cloze,...D.sorts.map(item=>({...item,kind:'sort'}))]}
function practiceHome(){const questions=filtered(D.questions),done=questions.filter(completed).length;$('#app').innerHTML=heading('Practice Test 2','Every answer includes a specific explanation. Missed items return after other questions until you answer them correctly.')+`<section class="focus"><div><h2>${done} of ${questions.length} guide topics completed</h2><p>Start with a short review or practice every topic in the selected chapter area.</p><div class="actions"><button class="primary" id="quick">Review 10</button><button id="all-guide">All guide topics</button><button id="mixed">Mix questions, terms, blanks, and sequences</button></div></div><div class="ring">${questions.length?Math.round(100*done/questions.length):0}%<small>COMPLETED</small></div></section>`+sectionCards()+`<div class="notice">A green completion bar means every selected guide topic has been answered correctly at least once. It does not guarantee an exam score.</div>`;$('#quick').onclick=()=>start('practice',shuffle(questions).slice(0,10));$('#all-guide').onclick=()=>start('practice',shuffle(questions));$('#mixed').onclick=()=>start('practice',shuffle(filtered(mixedPool())).slice(0,30))}

function prepare(item){if(item.kind==='cloze'){const answers=item.correct.split('; '),bank=shuffle([...answers,...item.distractors.filter(choice=>!answers.includes(choice))]);return {...item,bank,picked:[]}}if(item.kind==='sort')return {...item,current:shuffledOrder(item.items)};if(item.kind==='wordbank')return {...item,bank:shuffledOrder(item.exp.split(/\s+/).map((word,index)=>({word,index}))),picked:[]};const options=item.options?shuffle(item.options):shuffle([item.correct,...item.distractors]);return {...item,options}}
function start(mode,items,lessonNumber=null){if(!items.length){$('#app').innerHTML='<section class="card"><h2>No items in this selection</h2><button data-view="practice">Choose another topic</button></section>';return}session={mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber};renderSession();window.scrollTo(0,0)}
function preteach(item){const question=sourceQuestion(item);return `<details class="card"><summary>Show Explanation & Rule · Teach me first</summary><div class="lesson-copy">${paragraphs(item.teach)}${item.example||question?.example?`<h3>Picture the action</h3>${paragraphs(item.example||question.example)}`:''}</div></details>`}
function feedback(item,correct){const question=sourceQuestion(item),answer=item.kind==='sort'?item.items.join(' → '):item.kind==='wordbank'?item.exp:item.correct;return `<div class="feedback" role="status"><strong>${correct?'✓ Correct':'Not quite · try the idea again'}</strong><h3>Correct answer</h3>${paragraphs(answer)}<h3>Why this is correct</h3>${paragraphs(item.teach)}${item.example||question?.example?`<h3>What is physically or logically happening</h3>${paragraphs(item.example||question.example)}`:''}${question&&question.answer!==item.teach?`<details><summary>Read the complete study-guide answer</summary>${paragraphs(question.answer)}</details>`:''}${sourceDetails(item)}</div>`}
function sessionHeader(item){return `<div class="study"><div class="row spread"><span class="tag">${sectionLabel(item)}</span><button data-view="${session.mode==='flash'?'flash':session.mode==='exam'?'exam':session.mode==='exercise'?'exercises':'practice'}">End session</button></div><p class="tiny">${session.mode==='exam'?'Exam':session.mode==='flash'?'Flashcards':'Practice'} · ${Math.min(session.index+1,session.items.length)} / ${session.items.length}${!['exam','flash'].includes(session.mode)?` · ${session.cleared.size}/${session.total} cleared`:''}</p><div class="bar"><span style="width:${100*(['exam','flash'].includes(session.mode)?session.index:session.cleared.size)/session.total}%"></span></div>`}
function renderSession(){if(!session||session.index>=session.items.length){finish();return}chrome();const item=session.items[session.index];session.graded=false;session.revealed=false;if(session.mode==='flash'){renderFlash(item);return}if(item.kind==='cloze'){renderCloze(item);return}if(item.kind==='sort'){renderSort(item);return}if(item.kind==='wordbank'){renderWordBank(item);return}$('#app').innerHTML=sessionHeader(item)+`${item.exerciseNumber?`<p class="exercise-number">INSTRUCTOR EXERCISE ${item.exerciseNumber} OF 20</p>`:''}<h2 class="question">${esc(item.q)}</h2>${session.mode==='exam'?'':preteach(item)}<p class="eyebrow">CHOOSE ONE ANSWER</p><div class="choices">${item.options.map((option,index)=>`<button data-option="${index}"><b>${String.fromCharCode(65+index)}.</b><span>${esc(option)}</span></button>`).join('')}</div><div id="feedback"></div></div>`;document.querySelectorAll('[data-option]').forEach(button=>button.onclick=()=>{if(session.graded)return;const selected=item.options[+button.dataset.option],correct=selected===item.correct;document.querySelectorAll('[data-option]').forEach(choice=>{choice.disabled=true;if(item.options[+choice.dataset.option]===item.correct)choice.classList.add('correct')});if(!correct)button.classList.add('wrong');grade(item,correct,selected)})}
function grade(item,correct,selected){if(session.graded)return;session.graded=true;session.lastOK=correct;if(!(item.id in session.first)){session.first[item.id]={correct,selected};if(correct)session.right++}if(correct)session.cleared.add(item.id);record(item,correct);$('#feedback').innerHTML=feedback(item,correct)+`<button class="primary" id="next">${session.index+1===session.items.length&&(correct||session.mode==='exam')?'See results':'Continue →'}</button>`;$('#next').onclick=advance}
function advance(){const item=session.items[session.index];if(!session.lastOK&&session.mode!=='exam')session.items.splice(Math.min(session.index+4,session.items.length),0,prepare(item));session.index++;renderSession();$('#app').focus()}
function finish(){const current=session;if(!current)return;const missed=Object.entries(current.first).filter(([,result])=>!result.correct).map(([id])=>current.items.find(item=>item.id===id)).filter(Boolean);if(current.mode!=='flash'){const signature=`${current.mode}:${current.total}:${current.items.slice(0,current.total).map(item=>item.id).join('|')}`;if(!progress.completedSessions.some(item=>item.signature===signature))progress.completedSessions.push({signature,mode:current.mode,total:current.total,right:current.right,date:Date.now()});save()}$('#app').innerHTML=`<div class="study"><section class="card"><span class="tag">${current.mode==='exam'?'EXAM FINISHED':'✓ COMPLETED'}</span><h1>${current.mode==='exam'?`${current.right} / ${current.total} on first answers`:current.mode==='flash'?'Recall round finished':'Every item cleared'}</h1><p>${current.mode==='exam'?'Your score keeps the first answer to each question.':`You successfully completed all ${current.total} items, including retries.`}</p><p>${missed.length} item${missed.length===1?'':'s'} needed another look on the first attempt.</p><div class="actions"><button class="primary" data-view="${current.mode==='exercise'?'exercises':current.mode==='exam'?'exam':'practice'}">Back</button>${missed.length?'<button id="retry-missed">Practice missed items</button>':''}${current.lessonNumber?`<button id="continue-learning">Continue learning</button>`:''}${current.mode==='subnet'?'<button id="fresh-subnet">New subnet · fresh numbers</button>':''}</div></section>${current.mode==='exam'?missed.map(item=>`<details class="card exam-review"><summary>${esc(item.q)}</summary>${feedback(item,false)}</details>`).join(''):''}</div>`;if($('#retry-missed'))$('#retry-missed').onclick=()=>start('practice',shuffle(missed));if($('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(current.lessonNumber);if($('#fresh-subnet'))$('#fresh-subnet').onclick=()=>{subnetCase=randomSubnetCase(subnetCase);start('subnet',subnetQuestions(subnetCase))}}

function renderCloze(item){let index=0;const sentence=esc(item.q).replace(/____/g,()=>{const slot=index++;return item.picked[slot]!==undefined?`<button data-blank-slot="${slot}">${esc(item.bank[item.picked[slot]])}</button>`:`<span class="tag">Blank ${slot+1}</span>`});const needed=item.correct.split('; ');$('#app').innerHTML=sessionHeader(item)+`<h2>Complete the sentence</h2><p>Tap one phrase for each blank. Tap a filled blank to remove it.</p><section class="card lesson-copy">${sentence}</section>${session.mode==='exam'?'':preteach(item)}<div class="actions">${item.bank.map((word,i)=>`<button data-blank-word="${i}" ${item.picked.includes(i)||item.picked.length===needed.length?'disabled':''}>${esc(word)}</button>`).join('')}</div><div class="actions"><button id="check-blanks" class="primary" ${item.picked.length===needed.length?'':'disabled'}>Check sentence</button><button id="clear-blanks">Start over</button></div><div id="feedback"></div></div>`;document.querySelectorAll('[data-blank-word]').forEach(button=>button.onclick=()=>{item.picked.push(+button.dataset.blankWord);renderCloze(item)});document.querySelectorAll('[data-blank-slot]').forEach(button=>button.onclick=()=>{item.picked.splice(+button.dataset.blankSlot,1);renderCloze(item)});$('#clear-blanks').onclick=()=>{item.picked=[];renderCloze(item)};$('#check-blanks').onclick=()=>{const answer=item.picked.map(i=>item.bank[i]).join('; ');grade(item,answer===item.correct,answer)}}
function renderSort(item){$('#app').innerHTML=sessionHeader(item)+`<h2>${esc(item.q)}</h2><p>Move the pieces until the process runs from first to last.</p>${preteach(item)}<div class="order">${item.current.map((value,index)=>`<div><strong>${index+1}</strong><span>${esc(value)}</span><button data-up="${index}" ${index===0?'disabled':''}>↑</button><button data-down="${index}" ${index===item.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button id="check-sort" class="primary">Check order</button><div id="feedback"></div></div>`;for(const direction of ['up','down'])document.querySelectorAll(`[data-${direction}]`).forEach(button=>button.onclick=()=>{const index=+button.dataset[direction],other=index+(direction==='up'?-1:1);[item.current[index],item.current[other]]=[item.current[other],item.current[index]];renderSort(item)});$('#check-sort').onclick=()=>grade(item,item.current.every((value,index)=>value===item.items[index]),item.current.join(' → '))}
function renderWordBank(item){const chosen=item.picked.map(index=>item.bank[index]),complete=chosen.length===item.bank.length;$('#app').innerHTML=sessionHeader(item)+`<h2>${esc(item.q)}</h2><p>Tap the words in order to build the full name.</p>${preteach(item)}<div class="word-answer">${chosen.map((token,index)=>`<button data-picked="${index}">${esc(token.word)}</button>`).join('')||'<span class="muted">Your phrase appears here</span>'}</div><div class="wordbank">${item.bank.map((token,index)=>`<button data-bank="${index}" ${item.picked.includes(index)?'disabled':''}>${esc(token.word)}</button>`).join('')}</div><div class="actions"><button id="check-wordbank" class="primary" ${complete?'':'disabled'}>Check phrase</button><button id="clear-wordbank">Start over</button></div><div id="feedback"></div></div>`;document.querySelectorAll('[data-bank]').forEach(button=>button.onclick=()=>{item.picked.push(+button.dataset.bank);renderWordBank(item)});document.querySelectorAll('[data-picked]').forEach(button=>button.onclick=()=>{item.picked.splice(+button.dataset.picked,1);renderWordBank(item)});$('#clear-wordbank').onclick=()=>{item.picked=[];renderWordBank(item)};$('#check-wordbank').onclick=()=>grade(item,chosen.map(token=>token.word).join(' ')===item.exp,chosen.map(token=>token.word).join(' '))}

function flashHome(){const questions=filtered(D.questions),terms=filtered(D.vocab);$('#app').innerHTML=heading('Flip it. Say it. Check it.','Think of the answer before revealing the back. The front never displays the answer.')+`<div class="grid"><section class="card"><h2>Study-guide cards</h2><p>${questions.length} complete Test 2 topics.</p><button class="primary" id="flash-guide">Study guide</button></section><section class="card"><h2>Vocabulary cards</h2><p>${terms.length} direct definitions and abbreviations.</p><button class="primary" id="flash-terms">Study terms</button></section></div>`;$('#flash-guide').onclick=()=>start('flash',shuffle(questions));$('#flash-terms').onclick=()=>start('flash',shuffle(terms))}
function renderFlash(item){const answer=item.answer||item.correct;$('#app').innerHTML=sessionHeader(item)+`<button class="flashcard" id="flip"><span class="eyebrow">${session.revealed?'ANSWER & EXPLANATION':'RECALL BEFORE REVEAL'}</span><h2>${session.revealed?esc(answer):esc(item.term?`What does ${item.term}${item.exp?' stand for and ': ' '}mean?`:item.q)}</h2>${session.revealed?paragraphs(item.teach)+(item.example?`<h3>Example</h3>${paragraphs(item.example)}`:''):'<p>Say the answer aloud, then tap to check.</p>'}</button>${session.revealed?'<div class="actions"><button id="again">Still learning</button><button class="primary" id="remembered">I remembered</button></div>':''}</div>`;$('#flip').onclick=()=>{session.revealed=!session.revealed;renderFlash(item)};if($('#again'))$('#again').onclick=()=>{session.lastOK=false;advance()};if($('#remembered'))$('#remembered').onclick=()=>{session.lastOK=true;session.cleared.add(item.id);record(item,true);advance()}}

function termsHome(){const terms=filtered(D.vocab);$('#app').innerHTML=heading('Every Test 2 term, defined','Definitions name the object, where it exists, what it does, and why the course uses it.')+`<label class="search-label">Find a term <input id="term-search" type="search" placeholder="Try: socket, recursive, metric, BSS…"></label><div id="term-list" class="wordlist"></div>`;const update=()=>{const query=$('#term-search').value.toLowerCase(),matches=terms.filter(item=>(item.term+' '+(item.exp||'')+' '+item.answer).toLowerCase().includes(query));$('#term-list').innerHTML=matches.map(item=>`<article><span class="tag">${sectionLabel(item)}</span><h3>${esc(item.term)}${item.exp?` · ${esc(item.exp)}`:''}</h3>${paragraphs(item.answer)}<details><summary>Why this matters</summary>${paragraphs(item.teach)}${paragraphs(item.example)}</details></article>`).join('')||'<p>No matching terms.</p>'};$('#term-search').oninput=update;update()}
function abbrevHome(){const terms=filtered(D.vocab).filter(item=>item.exp);$('#app').innerHTML=heading('Build every abbreviation','Choose the full name first, then rebuild it from a jumbled word bank.')+`<section class="card"><h2>${terms.length} abbreviations in this selection</h2><p>${terms.map(item=>esc(item.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrev-mc">Choose full names</button><button id="abbrev-build">Build full names</button></div></section>`;$('#abbrev-mc').onclick=()=>start('practice',shuffle(terms));$('#abbrev-build').onclick=()=>start('practice',shuffle(terms.map(item=>({...item,id:item.id+'-build',kind:'wordbank',q:`Build the full name of ${item.term}`}))))}
