function sortHome(){const items=filtered(D.sorts);$('#app').innerHTML=heading('Put the network actions in order','Rebuild handshakes, resolution sequences, routing processes, and subnetting steps from memory.')+`<div class="grid">${items.map(item=>`<section class="card"><span class="tag">${sectionLabel(item)}</span><h2>${esc(item.title)}</h2><p>${esc(item.q)}</p><button class="primary" data-sort="${item.id}">Sort ${item.items.length} steps</button></section>`).join('')}</div>`;document.querySelectorAll('[data-sort]').forEach(button=>button.onclick=()=>start('practice',[{...D.sorts.find(item=>item.id===button.dataset.sort),kind:'sort'}]))}

